<section class="content"><h1>Mis pedidos</h1><?php if(!$orders):?><div class="empty">Todavía no tenés pedidos.</div><?php else:?><table class="table"><tr><th>Número</th><th>Fecha</th><th>Estado</th><th>Total</th></tr><?php foreach($orders as $o):?><tr><td><a href="?action=order&n=<?=h($o['numero_pedido'])?>"><?=h($o['numero_pedido'])?></a></td><td><?=h($o['fecha_pedido'])?></td><td><?=h(order_status_label($o['estado']))?></td><td><?=ars($o['total'])?></td></tr><?php endforeach?></table><?php endif?></section>
